<template>
  <NuxtLink :to="{ name: 'workshifts-id', params: { id: workShiftId } }" class="flex items-center gap-2">
    <LabeledValueIcon
      :label="label || 'Work Shift'"
      :icon="ClockIcon"
      :loading="isLoading"
      :error="error ? 'Failed to load work shift' : undefined"
    >
      <div v-if="data">
        <span class="flex gap-2 flex-wrap items-center">
          <span v-if="data.net_hours != null" class="font-semibold">{{ formatHours(data.net_hours) }}</span>
          <Badge :variant="getWorkshiftStatusBadge(data.status).variant" size="sm">{{
            getWorkshiftStatusBadge(data.status).label
          }}</Badge>
        </span>
        <span class="text-sm text-muted-foreground">{{
          formatDateTzToFormat(new Date(data.start_time), 'MM/dd/yyyy, hh:mm aaa', timezone)
        }}</span>
      </div>
    </LabeledValueIcon>
  </NuxtLink>
</template>
<script setup lang="ts">
import { ClockIcon } from 'lucide-vue-next';
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';
import { getWorkShiftShortInfo } from '~/client';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';
import { formatHours } from '~/utils/formatHours';
import { getWorkshiftStatusBadge } from '~/constants/workshifts/workshiftStatuses';

const props = defineProps<{
  label?: string;
  workShiftId: string;
}>();

const { data, isLoading, error } = useQuery({
  key: () => ['workshift.short-info', props.workShiftId],
  query: () => getWorkShiftShortInfo({ composable: '$fetch', path: { work_shift_id: props.workShiftId } }),
  enabled: () => !!props.workShiftId,
});

const { timezone } = useUserRole();
</script>
